// flipkartOfferOut is one bank/card offer as reported to the user.
type flipkartOfferOut struct {
	AmountOff   float64 `json:"amount_off"`
	Description string  `json:"description"`
}

// flipkartOffersResult is the output shape of `product offers` (and the
// shared fetchProductOffers helper used by `offers best-card`).
type flipkartOffersResult struct {
	ProductID   string             `json:"product_id"`
	URL         string             `json:"url"`
	Price       float64            `json:"price"`
	MRP         float64            `json:"mrp,omitempty"`
	DiscountPct float64            `json:"discount_pct,omitempty"`
	Note        string             `json:"note,omitempty"`
	BankOffers  []flipkartOfferOut `json:"bank_offers"`
}

var (
	rupeeTokenRE = regexp.MustCompile(`₹\s*([0-9][0-9,]*)`)
	percentOffRE = regexp.MustCompile(`(?i)([0-9]+)\s*%\s*off`)
	bankAmountRE = regexp.MustCompile(`^₹\s*[0-9][0-9,]*\s*off$`)
)

// parseRupeeAmount parses a "1,234" or "1234" digit string (with optional
// commas) into a float64. Returns 0 on a malformed string rather than an
// error — callers treat 0 as "not found" per the "don't fabricate" rule.
func parseRupeeAmount(digits string) float64 {
	cleaned := strings.ReplaceAll(digits, ",", "")
	v, err := strconv.ParseFloat(cleaned, 64)
	if err != nil {
		return 0
	}
	return v
}

// formatRupeeAmount renders a price the way Flipkart's markup does
// ("1,799" for 1799), used to locate the price's rendered position in the
// page text so the MRP lookup can search nearby rather than globally.
func formatRupeeAmount(v float64) string {
	i := int64(math.Round(v))
	s := strconv.FormatInt(i, 10)
	if len(s) <= 3 {
		return s
	}
	// Indian digit grouping: last 3 digits, then groups of 2.
	var out []string
	out = append(out, s[len(s)-3:])
	rest := s[:len(s)-3]
	for len(rest) > 2 {
		out = append([]string{rest[len(rest)-2:]}, out...)
		rest = rest[:len(rest)-2]
	}
	if len(rest) > 0 {
		out = append([]string{rest}, out...)
	}
	return strings.Join(out, ",")
}

// parseMRPDiscount looks for two distinct rupee amounts near the known
// selling price in the page's visible text: the price itself, and a larger
// amount nearby which Flipkart renders as the struck-through MRP. Returns
// ok=false when the price string can't be located or no larger amount is
// found nearby — callers must leave MRP/discount unset rather than guess.
func parseMRPDiscount(visibleText string, price float64) (mrp float64, discountPct float64, ok bool) {
	if price <= 0 {
		return 0, 0, false
	}
	priceStr := formatRupeeAmount(price)
	idx := strings.Index(visibleText, "₹"+priceStr)
	if idx < 0 {
		return 0, 0, false
	}
	windowEnd := idx + 400
	if windowEnd > len(visibleText) {
		windowEnd = len(visibleText)
	}
	window := visibleText[idx:windowEnd]

	var mrpCandidate float64
	for _, m := range rupeeTokenRE.FindAllStringSubmatch(window, -1) {
		v := parseRupeeAmount(m[1])
		if v > price {
			mrpCandidate = v
			break
		}
	}
	if mrpCandidate == 0 {
		return 0, 0, false
	}

	discount := math.Round((mrpCandidate - price) / mrpCandidate * 100)
	if m := percentOffRE.FindStringSubmatch(window); m != nil {
		if n, err := strconv.Atoi(m[1]); err == nil {
			discount = float64(n)
		}
	}
	return mrpCandidate, discount, true
}

// collectVisibleTextTokens walks a parsed HTML document and returns each
// text node's trimmed content as a separate token (script/style subtrees
// are skipped so JSON-LD payloads and inline CSS don't pollute the token
// stream). Preserving per-node granularity (rather than joining into one
// string) is what lets parseBankOffers recognize the line-by-line
// "₹90 off / Apply / Flipkart Axis / Credit Card • Cashback" shape.
func collectVisibleTextTokens(doc *xhtml.Node) []string {
	var tokens []string
	var walk func(n *xhtml.Node)
	walk = func(n *xhtml.Node) {
		if n == nil {
			return
		}
		if n.Type == xhtml.ElementNode && (strings.EqualFold(n.Data, "script") || strings.EqualFold(n.Data, "style")) {
			return
		}
		if n.Type == xhtml.TextNode {
			t := strings.TrimSpace(n.Data)
			if t != "" {
				tokens = append(tokens, t)
			}
		}
		for c := n.FirstChild; c != nil; c = c.NextSibling {
			walk(c)
		}
	}
	walk(doc)
	return tokens
}

// visibleTextJoined renders the token stream as a single space-joined
// string, used by parseMRPDiscount's substring search for the rendered
// price.
func visibleTextJoined(tokens []string) string {
	return strings.Join(tokens, " ")
}

// parseBankOffers scans a visible-text token stream for a "Bank offers"
// heading and parses the repeating `₹<amount> off / Apply / <bank name>
// / <instrument type>` groups that follow it, per the verified-live shape:
//
//	Bank offers
//	₹90 off
//	Apply
//	Flipkart Axis
//	Credit Card • Cashback
//
// merged into {amount_off: 90, description: "Flipkart Axis Credit Card •
// Cashback"}, dropping literal "Apply" tokens. Stops as soon as a token
// that isn't itself a "₹N off" amount appears where the next offer's
// amount was expected, so unrelated later sections (coupons, similar
// products) are never misread as bank offers. Returns nil, not an error,
// when no "Bank offers" heading is found — some products have none.
func parseBankOffers(tokens []string) []flipkartOfferOut {
	headerIdx := -1
	for i, t := range tokens {
		if strings.EqualFold(t, "Bank offers") || strings.EqualFold(t, "Bank offer") {
			headerIdx = i
			break
		}
	}
	if headerIdx < 0 {
		return nil
	}

	var offers []flipkartOfferOut
	i := headerIdx + 1
	for i < len(tokens) {
		t := strings.TrimSpace(tokens[i])
		if t == "" {
			i++
			continue
		}
		if !bankAmountRE.MatchString(t) {
			break // section ended
		}
		m := rupeeTokenRE.FindStringSubmatch(t)
		if m == nil {
			break
		}
		amt := parseRupeeAmount(m[1])
		i++
		for i < len(tokens) && strings.EqualFold(strings.TrimSpace(tokens[i]), "Apply") {
			i++
		}
		var descParts []string
		for len(descParts) < 2 && i < len(tokens) {
			nt := strings.TrimSpace(tokens[i])
			if nt == "" {
				i++
				continue
			}
			if bankAmountRE.MatchString(nt) {
				break
			}
			descParts = append(descParts, nt)
			i++
		}
		if len(descParts) > 0 {
			offers = append(offers, flipkartOfferOut{AmountOff: amt, Description: strings.Join(descParts, " ")})
		}
	}
	return offers
}

var (
	trackingContentTypeRE  = regexp.MustCompile(`"contentType":"([^"]*)"`)
	trackingContentTitleRE = regexp.MustCompile(`"contentTitle":"([^"]*)"`)
	trackingPriceOffRE     = regexp.MustCompile(`"discountedPriceText":"₹\s*([0-9][0-9,]*)\s*off"`)
)

// parseBankOffersFromTrackingBlob is a fallback bank-offer extractor for
// when parseBankOffers finds nothing in the visible DOM text. Verified live
// against real product pages: Flipkart's bank-offers carousel is a
// virtualized widget whose row content (the "₹N off / Apply / <bank> /
// <instrument>" text the build spec described) is NOT present in
// server-rendered HTML — only an empty placeholder is. The same data does
// appear, however, in an analytics/tracking JSON blob embedded elsewhere in
// the page, shaped as repeated objects carrying
// "contentType":"OfferDetails:Bank offers", a "contentTitle" (bank +
// instrument description, underscore-separated), and a sibling
// "discountedPriceText":"₹N off". This walks that blob with anchored
// regexes rather than a full JSON parse (the blob is deeply nested,
// vendor-internal, and only these three fields are needed), scoping every
// match to the nearest *preceding* contentType so unrelated sections
// (coupons, EMI options) that might reuse "discountedPriceText" elsewhere
// are not misread as bank offers. Deduplicates identical (amount,
// description) pairs, since the same offer is repeated across multiple UI
// states (logged-in pill, detail sheet, login-required variant) in the blob.
func parseBankOffersFromTrackingBlob(raw []byte) []flipkartOfferOut {
	s := string(raw)
	priceMatches := trackingPriceOffRE.FindAllStringSubmatchIndex(s, -1)
	if len(priceMatches) == 0 {
		return nil
	}
	typeMatches := trackingContentTypeRE.FindAllStringSubmatchIndex(s, -1)
	titleMatches := trackingContentTitleRE.FindAllStringSubmatchIndex(s, -1)

	type offerKey struct {
		amount float64
		desc   string
	}
	seen := map[offerKey]bool{}
	var out []flipkartOfferOut
	for _, pm := range priceMatches {
		amt := parseRupeeAmount(s[pm[2]:pm[3]])
		if amt <= 0 {
			continue
		}
		contentType := nearestPreceding(s, typeMatches, pm[0])
		if !strings.Contains(strings.ToLower(contentType), "bank offers") {
			continue
		}
		desc := nearestPreceding(s, titleMatches, pm[0])
		desc = strings.ReplaceAll(strings.TrimLeft(desc, "_"), "_", " ")
		desc = strings.TrimSpace(desc)
		if desc == "" {
			continue
		}
		key := offerKey{amount: amt, desc: desc}
		if seen[key] {
			continue
		}
		seen[key] = true
		out = append(out, flipkartOfferOut{AmountOff: amt, Description: desc})
	}
	return out
}

// nearestPreceding returns the captured group of the last regex match in
// matches (as produced by FindAllStringSubmatchIndex) whose match start is
// at or before beforePos, or "" if none precede it.
func nearestPreceding(s string, matches [][]int, beforePos int) string {
	result := ""
	for _, m := range matches {
		if m[0] > beforePos {
			break
		}
		result = s[m[2]:m[3]]
	}
	return result
}

// fetchProductOffers fetches a product page (a separate fetch from
// fetchProductDetail — deliberately not sharing a cached body, per the
// build spec's "don't over-engineer caching" guidance) and extracts
// MRP/discount and bank offers from the rendered HTML. The JSON-LD is also
// parsed to recover the authoritative selling price used to anchor the MRP
// search. Shared by `product offers` and `offers best-card`.
func fetchProductOffers(ctx context.Context, httpClient *http.Client, rawURL string) (*flipkartOffersResult, error) {
	pid, err := pidFromURL(rawURL)
	if err != nil {
		return nil, err
	}
	status, body, err := fetchRawURL(ctx, httpClient, rawURL)
	if err != nil {
		return nil, err
	}
	if status != 200 {
		return nil, &fetchStatusError{URL: rawURL, StatusCode: status}
	}

	ldRaw, err := extractHTMLResponse(body, htmlExtractionOptions{
		Mode:           "embedded-json",
		BaseURL:        rawURL,
		ScriptSelector: "script#jsonLD",
		JSONPath:       "",
	})
	if err != nil {
		return nil, fmt.Errorf("extracting product JSON-LD from %s: %w", rawURL, err)
	}
	var ld []flipkartProductLD
	if err := json.Unmarshal(ldRaw, &ld); err != nil || len(ld) == 0 {
		return nil, fmt.Errorf("no product JSON-LD found at %s (page may not be a product detail page)", rawURL)
	}
	price := ld[0].Offers.Price

	doc, err := xhtml.Parse(strings.NewReader(string(body)))
	if err != nil {
		return nil, fmt.Errorf("parsing HTML from %s: %w", rawURL, err)
	}
	tokens := collectVisibleTextTokens(doc)

	bankOffers := parseBankOffers(tokens)
	if len(bankOffers) == 0 {
		// Fall back to the analytics/tracking JSON blob — see
		// parseBankOffersFromTrackingBlob for why the DOM-text shape the
		// build spec described is frequently absent from server-rendered
		// HTML.
		bankOffers = parseBankOffersFromTrackingBlob(body)
	}

	result := &flipkartOffersResult{
		ProductID:  pid,
		URL:        rawURL,
		Price:      price,
		BankOffers: bankOffers,
	}
	if mrp, discount, ok := parseMRPDiscount(visibleTextJoined(tokens), price); ok {
		result.MRP = mrp
		result.DiscountPct = discount
	} else {
		result.Note = "could not reliably resolve MRP/discount from the rendered page; left unset rather than guessing"
	}
	if result.BankOffers == nil {
		result.BankOffers = []flipkartOfferOut{}
	}
	return result, nil
}

func newProductOffersCmd(flags *rootFlags) *cobra.Command {
	cmd := &cobra.Command{
		Use:   "offers <product-url>",
		Short: "Resolve MRP, discount percentage, and bank/card offers for a Flipkart product.",
		Long: `Fetches the given Flipkart product URL and extracts MRP, discount percentage,
and bank/card offers from the rendered page (none of these appear in the
page's schema.org JSON-LD, so they're parsed from visible page text).`,
		Example: strings.Trim(`
  flipkart-pp-cli product offers "https://www.flipkart.com/oppo-a3x-8-gb-ram-128-gb-storage-lake-green/p/itmc050065f36601?pid=MOBH4ZCFEQZFQBFB"
`, "\n"),
		Annotations: map[string]string{"mcp:read-only": "true"},
		RunE: func(cmd *cobra.Command, args []string) error {
			if len(args) == 0 {
				return cmd.Help()
			}
			productURL := args[0]

			if dryRunOK(flags) {
				fmt.Fprintf(cmd.ErrOrStderr(), "would fetch product page and parse MRP/discount/bank offers: %s\n(dry run - no request sent)\n", productURL)
				return nil
			}

			c, err := flags.newClient()
			if err != nil {
				return err
			}

			result, err := fetchProductOffers(cmd.Context(), c.HTTPClient, productURL)
			if err != nil {
				return classifyFetchErr(err)
			}

			db, err := store.OpenWithContext(cmd.Context(), defaultDBPath("flipkart-pp-cli"))
			if err != nil {
				return fmt.Errorf("opening local database: %w", err)
			}
			defer db.Close()
			if err := db.EnsureFlipkartSchema(); err != nil {
				return err
			}

			now := time.Now()
			if err := db.UpsertFlipkartProductMRP(result.ProductID, result.URL, result.MRP, result.DiscountPct); err != nil {
				return fmt.Errorf("storing MRP/discount: %w", err)
			}
			storeOffers := make([]store.FlipkartOffer, 0, len(result.BankOffers))
			for _, o := range result.BankOffers {
				storeOffers = append(storeOffers, store.FlipkartOffer{AmountOff: o.AmountOff, Description: o.Description})
			}
			if err := db.ReplaceFlipkartOffers(result.ProductID, storeOffers, now); err != nil {
				return fmt.Errorf("storing bank offers: %w", err)
			}

			return printJSONFiltered(cmd.OutOrStdout(), result, flags)
		},
	}
	return cmd
}
